import os,re
pats = {
 'anthropic_key': re.compile(rb'sk-ant-[A-Za-z0-9_\-]{10,}'),
 'gh_token': re.compile(rb'gh[pousr]_[A-Za-z0-9]{20,}'),
 'aws': re.compile(rb'AKIA[0-9A-Z]{16}'),
 'bearer': re.compile(rb'Bearer\s+[A-Za-z0-9\-_\.]{20,}'),
 'privkey': re.compile(rb'-----BEGIN [A-Z ]*PRIVATE KEY-----'),
 'oauth': re.compile(rb'"accessToken"\s*:\s*"[^"]{10,}'),
 'passwordish': re.compile(rb'(?i)"(password|passwd|secret|api_?key)"\s*:\s*"[^"]{6,}'),
 'mongo_uri': re.compile(rb'mongodb(\+srv)?://[^"\s]*:[^"@\s]*@'),
}
hits={}
for root,dirs,files in os.walk('.'):
    for f in files:
        p=os.path.join(root,f)
        b=open(p,'rb').read()
        for name,rx in pats.items():
            for m in rx.finditer(b):
                hits.setdefault(name,[]).append((p, m.group()[:80]))
for k,v in hits.items():
    print('==',k,len(v))
    for p,s in v[:6]: print('   ',p,s[:100])
if not hits: print("no credential-shaped matches")
EOF

