import json,os,re
# find dotted keys
def walk(o, path=""):
    if isinstance(o,dict):
        for k,v in o.items():
            if "." in k or k.startswith("$"): yield path+"/"+k
            yield from walk(v, path+"/"+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v, path+f"[{i}]")
hits={}
for root,dirs,files in os.walk('.'):
    for f in files:
        if not f.endswith('.jsonl'): continue
        p=os.path.join(root,f)
        for i,raw in enumerate(open(p,'rb').read().splitlines(),1):
            try: d=json.loads(raw)
            except Exception: continue
            ks=list(walk(d))
            if ks:
                hits.setdefault((p,d.get("type")),[]).append((i,len(ks),ks[:3]))
for (p,t),v in hits.items():
    print(p,t,"lines:",[x[0] for x in v][:12], "example keys:", v[0][2])
EOF

